export const PR_METADATA_QUERY =
  "# This cheap ordered index decides which PRs may have changed before activity is requested.\nquery PRMetadata($owner: String!, $name: String!, $first: Int!, $after: String) {\n  rateLimit {\n    cost\n    remaining\n    nodeCount\n  }\n  repository(owner: $owner, name: $name) {\n    pullRequests(states: OPEN, first: $first, after: $after, orderBy: { field: UPDATED_AT, direction: DESC }) {\n      pageInfo {\n        hasNextPage\n        endCursor\n      }\n      nodes {\n        number\n        updatedAt\n      }\n    }\n  }\n}";
